 m=json.loads((a.kit/'manifest.json').read_text());canvas=Image.open(a.kit/m['base']).convert('RGBA')
 parts=[p for x in m['assets'] if a.only is None or x['id'] in a.only for p in x['render_parts']]
 for part in sorted(parts,key=lambda p:p['z']):
  im=Image.open(a.kit/part['file']).convert('RGBA');size=tuple(max(1,round(x)) for x in part['size_wh'])
